+    // Search for links. Two tags may share storage only when the actual type
+    // stored there is valid for both tag signatures. Otherwise following the
+    // link could place one tag's cooked representation in the other tag's slot.
+    for (i = 0; i < Icc->TagCount; i++) {
+        cmsTagDescriptor* TagDescriptor;
+        cmsTagTypeSignature BaseType;
+
+        if (Icc->TagSizes[i] < sizeof(_cmsTagBase))
+            continue;
+
+        TagDescriptor = _cmsGetTagDescriptor(Icc->ContextID, Icc->TagNames[i]);
+        if (TagDescriptor == NULL)
+            continue;
+
+        if (!io->Seek(io, Icc->TagOffsets[i]))
+            continue;
+
+        BaseType = _cmsReadTypeBase(io);
+        if (BaseType == 0 || !IsTypeSupported(TagDescriptor, BaseType))
+            continue;
+
+        for (j = 0; j < i; j++) {
+            cmsTagDescriptor* LinkedDescriptor;
+
+            if (Icc->TagOffsets[j] != Icc->TagOffsets[i] ||
+                Icc->TagSizes[j] != Icc->TagSizes[i])
+                continue;
+
+            LinkedDescriptor = _cmsGetTagDescriptor(Icc->ContextID, Icc->TagNames[j]);
+            if (LinkedDescriptor != NULL && IsTypeSupported(LinkedDescriptor, BaseType)) {
+                Icc->TagLinked[i] = Icc->TagNames[j];
+                break;
+            }
+        }
+    }
+
     return TRUE;
 }

